={{ (() => {
    const event = $json.event || {}
    const details = event.details || {}
    const recovered = $json.action === 'recovered'
    const severity = String(event.severity || 'error').toLowerCase()
    const state = String(event.state || (recovered ? 'healthy' : 'unknown')).toLowerCase()
    const subject = event.title || [
        details.host || event.execution?.host || event.source || 'Wormlogic',
        details.service || details.condition || event.category || 'operational event',
    ].filter(Boolean).join(' — ')
    const vantage = event.execution?.vantage
    const showVantage = vantage && !['local', 'none', 'unknown', 'n/a'].includes(String(vantage).toLowerCase())
    const emoji = recovered ? '🟢' : severity === 'warning' ? '🟠' : '🔴'
    const color = recovered || state === 'healthy' ? 5763719 : severity === 'warning' ? 16705372 : 15158332
    const summary = details.summary || (recovered ? `${subject} has recovered.` : `${subject} is ${state}.`)
    const lines = [
        summary,
        '',
        `**Severity:** ${severity}`,
        `**State:** ${state}`,
        ...(showVantage ? [`**Vantage:** ${event.execution?.host || 'unknown'} / ${vantage}`] : []),
        '',
        '**Reason**',
        event.message || 'No reason supplied.',
    ]
    return JSON.stringify({
        title: `${details.test ? '[TEST] ' : ''}${emoji} ${subject} — ${recovered ? 'RECOVERED' : state.toUpperCase()}`,
        description: lines.join(String.fromCharCode(10)),
        color,
        timestamp: event.occurred_at,
    })
})() }}
